eAfterTarget","type":"boolean","label":"Chuyển về sau target (chạy thử)","default":true},{"name":"groupPostShareFromPost","type":"boolean","label":"Chia sẻ bài viết nguồn vào nhóm","default":false},{"name":"groupPostShareCaption","type":"textarea","label":"Nội dung kèm bài chia sẻ","default":""}],"default_variables":{"images":[],"runAsPage":false,"sourceLink":"","inputDataUid":"","runAsPageUid":"","enableComment":false,"runAsPageName":"","campaignContent":"","commentIterations":[],"pageIdentityReady":false,"includeSourceImages":false,"originalIdentityName":"","copyContentFromSource":false,"groupPostShareTargets":[],"sourceContentAiPrompt":"","autoJoinGroupAfterPost":false,"groupPostShareMaxCount":0,"formattedContentEnabled":false,"pageIdentityRestoreOnly":false,"rewriteSourceContentWithAI":false,"leaveGroupOnPendingApproval":false,"pageIdentityRestoreAfterTarget":true,"campaignContentPreparationVersion":1,"enableGroupPostShareToJoinedGroups":false,"groupPostShareFromPost":false,"groupPostShareCaption":"","groupPostShareWorkflowVersion":1,"resultStatusDeclarations":[{"actionCode":"fb_post_group","statusCodes":["campaign_detail_skipped","campaign_detail_success","campaign_detail_error"]}]}}$after_1$::jsonb;
 SELECT jsonb_agg(CASE WHEN (n->>'blockId')::bigint<0 THEN jsonb_set(n,'{blockId}',to_jsonb((SELECT id FROM public.auto_blocks WHERE name=n->>'blockName'))) ELSE n END ORDER BY ord)
 INTO nodes FROM jsonb_array_elements(target->'nodes') WITH ORDINALITY a(n,ord);
 target := jsonb_set(target,'{nodes}',nodes);
 SELECT to_jsonb(w) INTO current_row FROM public.auto_workflows w WHERE w.name=baseline->>'name' FOR UPDATE;
 IF (SELECT count(*) FROM public.auto_workflows WHERE name=baseline->>'name')<>1 OR current_row IS NULL OR (current_row-'created_at'-'updated_at' IS DISTINCT FROM target-'created_at'-'updated_at' AND current_row-'created_at'-'updated_at' IS DISTINCT FROM baseline-'created_at'-'updated_at')
 THEN RAISE EXCEPTION 'native_group_share_rollback_drift: %',baseline->>'name'; END IF;
 UPDATE public.auto_workflows SET nodes=baseline->'nodes',edges=baseline->'edges',default_variables=baseline->'default_variables',variables_schema=baseline->'variables_schema',updated_at=now() WHERE name=baseline->>'name';
END $rollback$;
COMMIT;
